import React, { useState } from 'react';
import axios from 'axios';
import { useHistory } from 'react-router-dom';

const TeacherRegisterPage = () => {
  const [formData, setFormData] = useState({
    email: '',
    password: '',
    name: '',
    branch: ''
  });
  const [error, setError] = useState('');
  const history = useHistory();

  const { email, password, name, branch } = formData;

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await axios.post(`${process.env.REACT_APP_API_URL}/api/auth/teacher/register`, formData);
      history.push('/teacher-login');
    } catch (err) {
      setError('Registration failed. Please check your details.');
    }
  };

  return (
    <div>
      <h2>Teacher Registration</h2>
      <form onSubmit={handleSubmit}>
        <input type="text" name="name" placeholder="Name" value={name} onChange={handleChange} required />
        <input type="email" name="email" placeholder="College Email" value={email} onChange={handleChange} required />
        <input type="password" name="password" placeholder="Password" value={password} onChange={handleChange} required />
        <input type="text" name="branch" placeholder="Branch" value={branch} onChange={handleChange} required />
        <button type="submit">Register</button>
      </form>
      {error && <div style={{ color: 'red' }}>{error}</div>}
    </div>
  );
};

export default TeacherRegisterPage;