import React from 'react';
import { BrowserRouter as Router, Route, Switch } from 'react-router-dom';
import HomePage from './pages/HomePage';
import LeavePage from './pages/LeavePage';
import StudentLoginPage from './pages/StudentLoginPage';
import TeacherLoginPage from './pages/TeacherLoginPage';
import HodLoginPage from './pages/HodLoginPage';
import StudentRegisterPage from './pages/StudentRegisterPage';
import TeacherRegisterPage from './pages/TeacherRegisterPage';
import HodRegisterPage from './pages/HodRegisterPage';
import StudentDashboard from './components/StudentDashboard';
import TeacherDashboard from './components/TeacherDashboard';
import HodDashboard from './components/HodDashboard';
import Header from './components/Header';
import Footer from './components/Footer';
import PrivateRoute from './components/PrivateRoute';

const App = () => {
  return (
    <Router>
      <Header />
      <Switch>
        <Route path="/" exact component={HomePage} />
        <Route path="/student-login" component={StudentLoginPage} />
        <Route path="/teacher-login" component={TeacherLoginPage} />
        <Route path="/hod-login" component={HodLoginPage} />
        <Route path="/student-register" component={StudentRegisterPage} />
        <Route path="/teacher-register" component={TeacherRegisterPage} />
        <Route path="/hod-register" component={HodRegisterPage} />
        <PrivateRoute path="/student/dashboard" component={StudentDashboard} />
        <PrivateRoute path="/teacher/dashboard" component={TeacherDashboard} />
        <PrivateRoute path="/hod/dashboard" component={HodDashboard} />
        <PrivateRoute path="/leave" component={LeavePage} />
      </Switch>
      <Footer />
    </Router>
  );
};

export default App;