import React from 'react';
import { Link } from 'react-router-dom';

const HomePage = () => {
  return (
    <div>
      <h1>Welcome to the College Leave System</h1>
      <div>
        <h2>Create an Account</h2>
        <ul>
          <li><Link to="/student-register">Student Registration</Link></li>
          <li><Link to="/teacher-register">Teacher Registration</Link></li>
          <li><Link to="/hod-register">HOD Registration</Link></li>
        </ul>
      </div>
      <div>
        <h2>Login</h2>
        <ul>
          <li><Link to="/student-login">Student Login</Link></li>
          <li><Link to="/teacher-login">Teacher Login</Link></li>
          <li><Link to="/hod-login">HOD Login</Link></li>
        </ul>
      </div>
    </div>
  );
};

export default HomePage;